"""Transaction isolation, locking, durable storage, index access, and bounded database workloads."""

WORLD = "sw-databases-transactions-v0"
PREFIX = "dbt"
DOMAIN = "distributed-cloud-data"
SUBJECT = "distributed-cloud-data.transactions"
SOURCES = ["postgresql18-docs", "berenson-1995-isolation", "leveldb-1-23"]
SCOPE = "PostgreSQL 18 transaction, MVCC, locking, WAL and index behavior; the explicit finite-history locking model discussed by Berenson et al. in 1995; LevelDB 1.23 LSM storage; and declared local query-round-trip and connection-pool models, with durability, serializability, liveness and performance kept distinct."
ROOT_LABEL = "Database transactions causation world"
ROOT_STATEMENT = "Root of the database transactions causation world: how visibility rules, synchronization, recovery ordering, indexed layouts and application resource use admit or prevent particular anomalies and determine bounded storage or query work."
LIMITATIONS = [
    "All prose is original. An isolation-level name is interpreted only within its named implementation or historical formal model; PostgreSQL Repeatable Read is not substituted for the minimum SQL phenomenon table.",
    "A serialization guarantee concerns successful committed histories. It neither guarantees that an attempted transaction commits nor provides an automatic exactly-once boundary for external side effects.",
    "Durability statements assume the named flush configuration and a storage stack that actually honors its persistence contract; WAL recovery is not protection against destruction of every durable copy.",
    "PostgreSQL heap and secondary B-tree indexes are distinct from the separately named LevelDB LSM implementation. Neither layout has an unconditional performance advantage over the other.",
    "Planner costs, I/O ratios and pool bounds belong to explicitly stated models and populations. They are not promises about measured latency, fairness or application correctness.",
]

